//! Usage records — metering events and health observations (produced at the edge,
//! aggregated at the center).

use super::SyncMeta;
use serde::{Deserialize, Serialize};

/// Metering event for one request (produced at the edge, aggregated back at the center).
///
/// Core payload of the edge→center data flow; `meta.key` is globally unique, and the center uses
/// it for idempotent deduplication.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct UsageEventRecord {
    /// = SyncMeta.key, a UUIDv7 generated by the edge (time-ordered).
    pub meta: SyncMeta,
    pub token_key: String,
    pub user_key: String,
    pub channel_key: String,
    pub route_unit_key: String,
    /// Effective group (authoritative for routing: `RouteUnitRecord::group` of the winning
    /// candidate; filled in at the settlement point; see the `usage_logs.group_id` comment in
    /// migration 0002 for how the write side picks the value).
    ///
    /// `#[serde(default)]`: this struct is the edge→center payload, so new fields must deserialize
    /// from values serialized by older edges (which lack the `groupId` field); a missing field
    /// falls back to the empty string.
    #[serde(default)]
    pub group_id: String,
    pub public_model: String,
    pub upstream_model: String,
    pub prompt_tokens: u64,
    pub completion_tokens: u64,
    pub cached_tokens: u64,
    /// Prompt tokens written to the cache (Claude `cache_creation_input_tokens`,
    /// OpenAI `prompt_tokens_details.cache_write_tokens`). Quantity only; the
    /// pricing layer does not consume it.
    ///
    /// `#[serde(default)]`: older edges do not carry the field.
    #[serde(default)]
    pub cache_creation_tokens: u64,
    /// Reasoning/thinking tokens already included in `completion_tokens` (OpenAI
    /// `completion_tokens_details.reasoning_tokens`, Gemini `thoughtsTokenCount`).
    /// Quantity only; the pricing layer does not consume it.
    ///
    /// `#[serde(default)]`: older edges do not carry the field.
    #[serde(default)]
    pub reasoning_tokens: u64,
    /// Whether the request intended to stream (SSE). Persisted rows use it to distinguish
    /// streaming from non-streaming sources; failure-observation rows record the streaming intent
    /// at request time.
    pub is_stream: bool,
    /// First-token latency (streaming).
    pub first_token_ms: u32,
    pub duration_ms: u32,
    /// Billing amount for this call (internal units, same dimension as `UserRecord::quota`).
    pub cost: i64,
    /// Final upstream status code; 0 = connection failure.
    pub status_code: u16,
    /// Failure summary (truncated upstream error message), None on success.
    pub error: Option<String>,
    /// Upstream finish reason (the raw `choices[0].finish_reason` / `stop_reason` value that
    /// metering extracts from the **non-streaming** response body or the final streaming frame;
    /// not normalized across providers — offline fitting does its own bucketing of
    /// truncation-class values such as `length`/`max_tokens`).
    /// `None` = the response lacks the field / parsing failed / this path never received a
    /// successful upstream response (for example an observation row short-circuited before
    /// dispatch).
    ///
    /// `#[serde(default)]`: same compatibility discipline as [`Self::group_id`] — values
    /// serialized by older edges lack the `finishReason` field, so center deserialization falls
    /// back to `None`.
    #[serde(default)]
    pub finish_reason: Option<String>,
}

/// One upstream health observation (produced locally at the edge; optionally reported to the
/// center for global circuit breaking).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HealthObservationRecord {
    pub meta: SyncMeta,
    pub channel_key: String,
    /// Observed error category; values come from the `app_contract::error::ErrorCode` hierarchy.
    pub outcome: String,
    pub latency_ms: u32,
    pub observed_at: chrono::DateTime<chrono::Utc>,
}

